1	use std::collections::BTreeMap;
2	
3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// Why the MHPCO refuses to settle a claim at all.
15	#[derive(Debug)]
16	pub enum ClaimError {
17	    /// More damages of this item type were reported than the policy covers.
18	    MoreDamagesThanInsuredItems { item_type: String },
19	}
20	
21	impl std::fmt::Display for ClaimError {
22	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
23	        match self {
24	            Self::MoreDamagesThanInsuredItems { item_type } => write!(
25	                formatter,
26	                "more {item_type} damages were reported than the policy insures"
27	            ),
28	        }
29	    }
30	}
31	
32	/// What the MHPCO settles on a claim: the payout and the cap left on the
33	/// policy afterwards.
34	#[derive(Debug)]
35	pub struct ClaimResult {
36	    pub payout: u64,
37	    pub remaining_cap: u64,
38	}
39	
40	/// The single customer a scenario is quoted for.
41	pub struct Customer {
42	    pub years_with_mhpco: u32,
43	}
44	
45	pub struct Item {
46	    pub item_type: String,
47	    pub material: String,
48	    pub enchantment: u32,
49	    pub cursed: bool,
50	}
51	
52	const PROCESSING_FEE: u64 = 5;
53	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
54	const CAP_MULTIPLE_OF_INSURANCE_SUM: u64 = 2;
55	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
56	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
57	
58	const SWORD_INSURANCE_VALUE: u64 = 1000;
59	const AMULET_INSURANCE_VALUE: u64 = 600;
60	const COMPONENT_INSURANCE_VALUE: u64 = 250;
61	const SWORD_BASE_PREMIUM: u64 = 100;
62	const AMULET_BASE_PREMIUM: u64 = 60;
63	const STAFF_BASE_PREMIUM: u64 = 80;
64	const POTION_BASE_PREMIUM: u64 = 40;
65	const COMPONENT_BASE_PREMIUM: u64 = 25;
66	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
67	const COMPONENT_BLOCK_SIZE: usize = 3;
68	const CURSE_SURCHARGE_PERCENT: u64 = 50;
69	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
70	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
71	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
72	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
73	const LOYALTY_YEARS: u32 = 2;
74	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
75	
76	/// Components, such as runes and moonstones, are the parts the MHPCO insures
77	/// alongside main items and the only items the building-block offer covers.
78	fn is_component(item: &Item) -> bool {
79	    matches!(item.item_type.as_str(), "rune" | "moonstone")
80	}
81	
82	/// The MHPCO price list: the base premium the catalogue lists for one item.
83	fn base_premium(item: &Item) -> u64 {
84	    if is_component(item) {
85	        return COMPONENT_BASE_PREMIUM;
86	    }
87	    match item.item_type.as_str() {
88	        "amulet" => AMULET_BASE_PREMIUM,
89	        "staff" => STAFF_BASE_PREMIUM,
90	        "potion" => POTION_BASE_PREMIUM,
91	        _ => SWORD_BASE_PREMIUM,
92	    }
93	}
94	
95	/// The building-block offer is reserved for a group of exactly 3 alike
96	/// components; a larger group does not qualify, it is priced per component.
97	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
98	    alike_component_count == COMPONENT_BLOCK_SIZE
99	}
100	
101	/// The price the MHPCO charges for one group of alike components: the
102	/// building-block offer when the group qualifies, otherwise per component.
103	fn component_group_base_premium(count: usize) -> u64 {
104	    if qualifies_as_building_block(count) {
105	        COMPONENT_BLOCK_BASE_PREMIUM
106	    } else {
107	        count as u64 * COMPONENT_BASE_PREMIUM
108	    }
109	}
110	
111	/// Two components are "alike" when they share this key. For the MHPCO,
112	/// alike means the very same catalogue type: a rune and a moonstone are
113	/// never alike, so mixed component types form no building block.
114	fn alike_group_key(item: &Item) -> &str {
115	    &item.item_type
116	}
117	
118	/// The policy base premium: the sum of all insured items' base premiums,
119	/// with alike components priced per group so a block can be recognised.
120	fn policy_base_premium(items: &[Item]) -> u64 {
121	    let mut main_items_total = 0;
122	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
123	    for item in items {
124	        if is_component(item) {
125	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
126	        } else {
127	            main_items_total += base_premium(item);
128	        }
129	    }
130	
131	    main_items_total
132	        + alike_component_counts
133	            .values()
134	            .map(|count| component_group_base_premium(*count))
135	            .sum::<u64>()
136	}
137	
138	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
139	#[derive(Clone, Copy)]
140	enum Debtor {
141	    Customer,
142	    Mhpco,
143	}
144	
145	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
146	/// settles the direction by itself once it is known who owes whom: an amount
147	/// the customer owes is rounded up, an amount the office owes is rounded down.
148	/// Intermediate amounts stay fractional; only the final amount is rounded.
149	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
150	    match owed_by {
151	        Debtor::Customer => amount.ceil() as u64,
152	        Debtor::Mhpco => amount.floor() as u64,
153	    }
154	}
155	
156	/// A policy-wide modifier is measured against the policy base premium, the
157	/// sum of all item base premiums, never against a single item.
158	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
159	    policy_base_premium * percent as f64 / 100.0
160	}
161	
162	/// Every item in a quote is treated as a first insurance, so the initial
163	/// assessment surcharge is charged on the whole policy base premium.
164	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
165	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
166	}
167	
168	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
169	/// highly enchanted. This is the premium-side threshold; the claim-side
170	/// reimbursement clause judges enchantment by its own, stricter threshold.
171	fn is_highly_enchanted(item: &Item) -> bool {
172	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
173	}
174	
175	/// An item-specific risk surcharge is charged on the base premium of the
176	/// affected item, never on the policy total.
177	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
178	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
179	}
180	
181	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
182	/// item that brings two of them is surcharged for each.
183	fn item_risk_surcharge(item: &Item) -> f64 {
184	    let mut surcharge = 0.0;
185	    if item.cursed {
186	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
187	    }
188	    if is_highly_enchanted(item) {
189	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
190	    }
191	    surcharge
192	}
193	
194	/// Item-specific modifiers apply to the base premium of the affected item,
195	/// never to the policy total, so the policy owes the sum of the items' own
196	/// risk surcharges.
197	fn item_risk_surcharges(items: &[Item]) -> f64 {
198	    items.iter().map(item_risk_surcharge).sum()
199	}
200	
201	/// A long-standing customer, with at least two years of business with the
202	/// MHPCO, has earned the loyalty discount.
203	fn is_long_standing(customer: &Customer) -> bool {
204	    customer.years_with_mhpco >= LOYALTY_YEARS
205	}
206	
207	/// The loyalty discount is a policy-wide modifier, so it is measured against
208	/// the policy base premium.
209	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
210	    if is_long_standing(customer) {
211	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
212	    } else {
213	        0.0
214	    }
215	}
216	
217	/// A contract is a follow-up when the customer already holds at least one
218	/// other contract with the MHPCO; the customer's very first is not.
219	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
220	    contracts_already_held > 0
221	}
222	
223	/// Every contract after the customer's first earns the follow-up discount. It
224	/// is a policy-wide modifier, so it is measured against the policy base premium.
225	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
226	    if is_follow_up_contract(contracts_already_held) {
227	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
228	    } else {
229	        0.0
230	    }
231	}
232	
233	/// What the customer's standing with the MHPCO adds to or takes off the policy
234	/// base premium: the net of every policy-wide surcharge and discount. Positive
235	/// amounts raise the premium, negative amounts lower it.
236	fn policy_wide_modifiers(
237	    customer: &Customer,
238	    contracts_already_held: u32,
239	    policy_base_premium: f64,
240	) -> f64 {
241	    first_insurance_surcharge(policy_base_premium)
242	        - loyalty_discount(customer, policy_base_premium)
243	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
244	}
245	
246	/// The premium the policy earns before the processing fee: the policy base
247	/// premium, plus what the items' own risks cost, plus what the customer's
248	/// standing adjusts.
249	fn modified_policy_premium(
250	    customer: &Customer,
251	    contracts_already_held: u32,
252	    items: &[Item],
253	) -> f64 {
254	    let policy_base_premium = policy_base_premium(items) as f64;
255	    policy_base_premium
256	        + item_risk_surcharges(items)
257	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
258	}
259	
260	/// The MHPCO adds its processing fee to every premium at the very end, after
261	/// every surcharge and discount has been settled.
262	pub fn quote_premium(
263	    customer: &Customer,
264	    contracts_already_held: u32,
265	    items: &[Item],
266	) -> u64 {
267	    rounded_in_mhpco_favor(
268	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
269	        Debtor::Customer,
270	    )
271	}
272	
273	/// Damage to a very highly enchanted item is reimbursed at only half the
274	/// damage amount. This claim-side threshold is deliberately stricter than, and
275	/// separate from, the premium-side high-enchantment risk surcharge: an item can
276	/// be enchanted enough to cost more to insure yet not enough to be halved.
277	fn is_reimbursed_by_half(item: &Item) -> bool {
278	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
279	}
280	
281	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
282	/// before the deductible is taken off. Full reimbursement is the MHPCO's
283	/// standing position: it is both what an item with no clause receives and what
284	/// the dragon-material clause prescribes, so that clause asks for no share of
285	/// its own. Only the halving clause departs from full reimbursement, and it
286	/// wins wherever it applies.
287	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
288	    if is_reimbursed_by_half(damaged_item) {
289	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
290	    } else {
291	        damage.amount as f64
292	    }
293	}
294	
295	/// The deductible applies per damage event, after the reimbursement clauses.
296	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
297	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
298	}
299	
300	/// Which insured item a reported damage refers to. A damage names only a
301	/// catalogue type, so the policy is searched for an item of that type; the
302	/// reimbursement clauses are judged against the item found here, not the report.
303	fn insured_item_for<'a>(items: &'a [Item], damage: &Damage) -> &'a Item {
304	    items
305	        .iter()
306	        .find(|item| item.item_type == damage.item_type)
307	        .expect("the damaged item is insured by this policy")
308	}
309	
310	/// What the MHPCO owes for an incident filed against a policy: the sum of the
311	/// reimbursements its damages earn, rounded in the office's favor at the end.
312	pub fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
313	    let total: f64 = incident
314	        .damages
315	        .iter()
316	        .map(|damage| reimbursement_for(insured_item_for(items, damage), damage))
317	        .sum();
318	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
319	}
320	
321	/// The MHPCO price list also lists what each item is insured for.
322	fn insurance_value(item: &Item) -> u64 {
323	    if is_component(item) {
324	        return COMPONENT_INSURANCE_VALUE;
325	    }
326	    match item.item_type.as_str() {
327	        "amulet" => AMULET_INSURANCE_VALUE,
328	        _ => SWORD_INSURANCE_VALUE,
329	    }
330	}
331	
332	/// The insurance sum of a policy is the sum of its items' insurance values.
333	fn insurance_sum(items: &[Item]) -> u64 {
334	    items.iter().map(insurance_value).sum()
335	}
336	
337	/// The total payout per policy is capped at twice the insurance sum.
338	fn policy_cap(items: &[Item]) -> u64 {
339	    CAP_MULTIPLE_OF_INSURANCE_SUM * insurance_sum(items)
340	}
341	
342	/// How the cap limits one settlement: the MHPCO pays what the incident earned,
343	/// but never more than the cap the policy has left, and reports the cap that
344	/// survives the payout.
345	fn settled_within_cap(earned: u64, available_cap: u64) -> ClaimResult {
346	    let payout = earned.min(available_cap);
347	    ClaimResult {
348	        payout,
349	        remaining_cap: available_cap - payout,
350	    }
351	}
352	
353	/// How much of its cap a policy still has to pay out with, once earlier claims
354	/// have drawn on it. A cap can be drawn down until it is exhausted, and an
355	/// exhausted cap is simply nothing left, never a debt the policy owes back.
356	fn cap_remaining_on(items: &[Item], cap_already_consumed: u64) -> u64 {
357	    policy_cap(items).saturating_sub(cap_already_consumed)
358	}
359	
360	/// What the MHPCO settles on an incident filed against a policy: what the
361	/// incident earns, limited by the cap the policy has left.
362	/// Every reported damage must be covered by an insured item of its own: the
363	/// MHPCO refuses a claim that reports more damages of a type than it insures.
364	fn check_every_damage_has_an_insured_item(
365	    items: &[Item],
366	    incident: &Incident,
367	) -> Result<(), ClaimError> {
368	    for damage in &incident.damages {
369	        let reported = incident
370	            .damages
371	            .iter()
372	            .filter(|other| other.item_type == damage.item_type)
373	            .count();
374	        let insured = items
375	            .iter()
376	            .filter(|item| item.item_type == damage.item_type)
377	            .count();
378	        if reported > insured {
379	            return Err(ClaimError::MoreDamagesThanInsuredItems {
380	                item_type: damage.item_type.clone(),
381	            });
382	        }
383	    }
384	    Ok(())
385	}
386	
387	pub fn claim(
388	    items: &[Item],
389	    incident: &Incident,
390	    cap_already_consumed: u64,
391	) -> Result<ClaimResult, ClaimError> {
392	    check_every_damage_has_an_insured_item(items, incident)?;
393	    Ok(settled_within_cap(
394	        claim_payout(items, incident),
395	        cap_remaining_on(items, cap_already_consumed),
396	    ))
397	}
